actor ControlledInboxPriorityPort:SyntheticInboxPriorityPort {
    nonisolated let grants:[SyntheticInboxPriorityGrant]
    private var attempts:[InboxPriorityAttempt]=[]
    private var pending:[Int:CheckedContinuation<SyntheticInboxPriorityOutcome,any Error>]=[:],waiters:[Int:CheckedContinuation<Void,Never>]=[:]
    init(_ grants:[SyntheticInboxPriorityGrant]) {self.grants=grants}
    func execute(_ a:InboxPriorityAttempt) async throws -> SyntheticInboxPriorityOutcome {let i=attempts.count;attempts.append(a);return try await withCheckedThrowingContinuation {pending[i]=$0;waiters.removeValue(forKey:i)?.resume()}}
    func wait(_ i:Int) async {if pending[i]==nil {await withCheckedContinuation {waiters[i]=$0}}}
    func resolve(_ i:Int,_ value:SyntheticInboxPriorityOutcome) {pending.removeValue(forKey:i)!.resume(returning:value)}
    func fail(_ i:Int) {pending.removeValue(forKey:i)!.resume(throwing:ReadFailure.unavailable)}
    func recorded()->[InboxPriorityAttempt] {attempts}
}

