actor ControlledPriorityRepository:InboxPriorityRepository {
    private var pending:CheckedContinuation<InboxPrioritySource,Never>?,waiter:CheckedContinuation<Void,Never>?
    func source(_ c:InboxConversationFilesContext) async throws -> InboxPrioritySource {await withCheckedContinuation {pending=$0;waiter?.resume();waiter=nil}}
    func wait() async {if pending==nil {await withCheckedContinuation {waiter=$0}}}
    func resolve(_ value:InboxPrioritySource) {pending!.resume(returning:value);pending=nil}
}
